from pathlib import Path
import re
root = Path('.orchestra/tasks/V-1273')
patterns = {
    'absolute_system_path': r'/(?:usr|var|run|tmp|mnt|opt|home|root|srv|etc)/[^\s\x27\x22`<>),;]+',
    'network_identifier': r'https?://[^\s\x27\x22`<>]+|\b(?:\d{1,3}\.){3}\d{1,3}\b|[\w.-]+@[\w.-]+',
    'workspace_identifier': r'\bhub-[0-9a-f]{12,}\b|\bvmi\d+\b|pytest-of-[^/\s\x27\x22]+',
}
for p in sorted(root.rglob('*')):
    if p.is_file():
        data=p.read_text()
        counts={kind: len(re.findall(pattern,data)) for kind,pattern in patterns.items()}
        if any(counts.values()):
            print(p.name, counts)
            system=sorted(set(re.findall(patterns['absolute_system_path'],data)))
            print('  system-path classes:', sorted(set('/'+v.split('/')[1]+'/' for v in system)))
PY

